from io import StringIO

class TransitionMachine:
    def __init__(self, s, t):
        self.s = list(s)
        self.t = list(t)
        self.M = len(self.s)
        self.N = len(self.t)
        self.c = 0

    def count(self, pattern):
        count = 0
        for i in range(len(pattern)):
            if self.s[self.M - 1 - i] == pattern[i]:
                count += 1
        return count

    def transform(self, i):
        transitions = {
            (0, 2): (1, 2, 0),
            (0, 0): (1, 1, 0),
            (2, 0): (0, 0, 0),
            (2, 2): (1, 2, 1),
            (1, 1): (0, 2, 0),
        }
        new_s = []
        new_c = 0
        for j in range(len(self.s)):
            ci = self.c
            transition = (ci // self.M, ci % self.M)
            next_c = transitions[transition][self.c]
            if next_c != 0:
                choice = (
                    self.c + 1 if self.c < self.N else self.N
                )  # Avoid division by zero
                while choice <= self.N:
                    if self.t[choice - 1] != self.s[choice * self.M - 1]:
                        choice -= 1
                    else:
                        break
                if choice == self.N + 1:
                    self.c = max(next_c - self.M, 0)
                else:
                    self.c = choice
            else:
                self.c = min(next_c, self.c - self.M)
            self.s[j % self.M] = self.t[self.c]
            new_s.append(self.s[j % self.M])
        return ''.join(new_s)

    def process(self):
        result = []
        if self.c == 0:
            answer = 1 if all(x == '?' for x in self.s[:]) else 0
            result.append(str(answer))
            return ''.join(result)
        if self.M * self.N != len(self.s) or self.M * self.N != len(self.t):
            raise ValueError
        if self.transform(0) == self.t:
            while self.s != '?':
                self.s = self.transform(0)
                result.append('1')
            return ''.join(result)
        while self.s != '?':
            self.s = self.transform(0)
            result.append('0')
            if self.s == self.t:
                return ''.join(result[:-1])  # not found complete
        raise ValueError

def solve(input_data):
    machine = TransitionMachine(input_data[0], input_data[1])
    queries = input_data[2:]
    return machine.process().split()

