def can_place_stages(stages, K, area):
    segments = [((0, 0), stage) for stage in stages]
    segments.append((stage, ((sys.maxsize, sys.maxsize))) for stage in stages)
    segments.sort(key=lambda x: (x[0][0], x[0][1]))
    points = set()
    ongoing = [(0, stage)] for stage in stages
    for left, (ar, direction) in enumerate(segments[1:], 1):
        x, y = segments[0][0]
        while ar[0] >= x:
            for move in ongoing:
                _, stage = move
                if ar[1] - direction == 0 and abs(x - stage[1]) < y:
                    return False
                elif ar[0] == ar[1] and move != ongoing:
                    return False
            for move in ongoing:
                ar, _ = move
                x, stage = move
                continue
            right, stage = segments[left]
            if stage not in points:
                points.add(stage)
                continue
            for move in ongoing:
                _, last = move
                if ar[0] - direction == 0 and abs(last - ar[1]) < y:
                    return False
                elif ar[1] == ar[0] and move != ongoing:
                    return False
            ongoing = [(0, destination) for destination, direction in ongoing]
            continue
    return True


