from sys import stdin

def solve(n, b, c):
    # Generate the bitmasks for b and c
    b_mask = [0]*n
    c_mask = [0]*n

    for i in range(n):
        b_mask[i] = 1 << b[i]
        for j in range(i+1, n):
            c_mask[i] |= 1 << c[j] & b_mask[i]

    # Find the first mask that doesn't conflict with any blocks in c
    conflict = n+1
    for bit in range(n):
        existing_conflict = 0
        for i in range(n):
            if b_mask[i] & bit:
                existing_conflict += 1
                if existing_conflict > 1:
                    break
        if existing_conflict == 0:
            conflict = bit
            break

    # If no such mask exists, no solution
    if conflict == n+1:
        return '-1'

    # Build the array a
    a = [bit for bit in range(n) if b_mask[bit] & conflict]
    for bit in range(n):
        if not bit & conflict:
            a.append(bit)

    # Convert to decimal and print
    return ' '.join(map(str, a))

