# Bob's coordinates
points = [(0, 0), (3, 0), (2, 1), (4, 4), (1, 5)]

def is_convex(points):
    """Check if the points form a convex polygon."""
    def cross_product(p1, p2, p3):
        """Calculate the cross product of vectors."""
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    def sign(p, q, r):
        """Determine the sign of the cross product to check collinearity."""
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    if len(points) <= 2:
        return len(points) > 2

    # Start from the first point
    p = points[0]
    stack = [p]
    for q in points[1:]:
        while len(stack) >= 2 and sign(stack[-2], stack[-1], q) <= 0:
            stack.pop()
        stack.append(q)

    return len(stack) == len(points)

def largest_festival_area(points, k):
    maximal_area = 0
    for combinations in combinations(points, k):
        if is_convex(combination):
            points_matrix = np.array(combination).T
            a = points_matrix[0][1] - points_matrix[0][0]
            b = points_matrix[1][1] - points_matrix[1][0]
            c = points_matrix[0][0] * points_matrix[1][1] - points_matrix[1][0] * points_matrix[0][1]
            delta = np.sqrt(a**2 + b**2)
            minimal_hypotenuse = delta * 2 / (2 * c - delta)
            maximal_area = max(maximal_area, delta * minimal_hypotenuse)
    return np.round(maximal_area * 0.01, 2)

