        a = a % m
        y = (y - half * m) % m
    xt = (x + m) % m
    return (xt % mod + mod) % mod

def is_prime(n, k = 4):
    if n == 2 :
        return True;
    if n % 2 == 0 or n < 2 : 
        return False;
    r = int(n ** 0.5) + 1;
    for f in range(2, r):
        if n % f == 0:
            return False
    return True

def catalan_number(n, mod):
    if n == 0:
        return 1
    return (((factorial_number(2 * n, mod) * pow(factorial_number(n, mod), mod - 2, mod)) * pow(factorial_number(n, mod), mod - 2, mod)) % mod + mod) % mod

