from collections import defaultdict, deque

def build_uf(n):
    indices = list(range(n))
    rank = [1] * n
    def find(x):
        if x != indices[x]:
            indices[x] = find(indices[x])
        return indices[x]
    def union(x, y):
        ix = find(x)
        iy = find(y)
        if ix == iy: return
        if rank[ix] > rank[iy]:
            indices[iy] = ix
        else:
            indices[ix] = iy
            if rank[ix] == rank[iy]:
                rank[iy] += 1
    return indices, union

