import sys

def z_function(s):
    n = len(s)
    z = [0] * n

    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    return z

def smith_waterman(s, k):
    n = len(s)
    matrix = [[0] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, min(i + k, n)):
            if s[i] == s[j]:
                matrix[i][j] = matrix[i + 1][j + 1] + 1
            else:
                matrix[i][j] = max(matrix[i + 1][j], matrix[i][j + 1])

    return matrix[0][n - 1]

def smith_waterman_query(s, k, l, r):
    return smith_waterman(s, r - l) + k

