def min_additional_chairs(N, M, limits):
    """
    Calculate the minimum number of additional chairs needed to accommodate all people of the Takahashi clan
    at their designated chairs without exceeding their preferred range. If no additional chairs are needed, return 0.
    """
    chair_ranges = []
    for i, (L, R) in enumerate(limits):
        if R < L:  # Handle people who prefer chairs outside the range of other preferences
            chair_ranges.append((quantile(R, M-1), quantile(L, 0)))
        else:
            chair_ranges.append((min(R, quantile(L, M)), max(L, quantile(R, M))))
    chair_ranges.sort()
    cover_l, cover_r = 0.0, 0.0

    for lower, upper in chair_ranges:
        if cover_l <= lower < cover_r:
            continue
        if upper > cover_r:
            return M - max(lower, cover_l) - int(cover_r) + 1 + max(cover_r, upper) - int(upper)
        cover_l, cover_r = lower, upper

    return M - min(upper for _, upper in chair_ranges) - 1 + 1

def quantile(x, n):
    """Calculate the quantile x based on the ceil of n divisions."""
    L = len(x)
    comp = x[x < n]
    interval = L / n
    if not len(comp):
        if L % n < n and (L % n) == interval:
            return floor(x[interval])
        return min(x) + interval
    highest = comp[-1]
    for range_left in reversed(comp):
        lower = int(lower_bound(range_left))
        upper = int(highest + 1 - lower_bound(range_left))

        if range_left[lower] <= x < range_left[upper]:
            # We are in the valid interval, return fractional times the total interval.
            return float(x - lower_bound(range_left)) / interval

        if x >= highest:
            break

        highest = range_left[-1]

    if interval <= 10**6:
        return max_integer_fractional(part_value(interval, highest, x) * interval)
    return highest + int(highest + 1)

