def find_array(a, b, c):
    n = len(a)
    sum_b = sum(b)
    sum_c = sum(c)
    if sum_b != sum_c:
        return "-1"

    result = ['inf'] * n

    current_sum_b = 0
    current_sum_c = 0
    for i in range(n):
        b_mask = tuple(b[i] for b_i in b if b_i & a[i])
        c_mask = tuple(c[i] for c_i in c if c_i & a[i])

        if len(b_mask) == 1 and len(c_mask) == 1:
            a_bit = min(b_mask[0], c_mask[0])
            if a_bit is not 'inf':
                if current_sum_b < current_sum_c:
                    result[i] = a_bit
                    current_sum_b += (a_bit << i)
                elif current_sum_b > current_sum_c:
                    result[i] = max(b_mask[0], c_mask[0])
                    current_sum_c += (max(b_mask[0], c_mask[0]) << i)

        elif len(b_mask) == 0 or len(c_mask) == 0:
            if current_sum_b > current_sum_c or current_sum_b < current_sum_c:
                return "-1"

    for bit in range(40):
        ind = -1
        for i in range(n):
            if result[i] is 'inf' or result[i][bit] == 'neg':
                result[i] = 'inf'

            elif result[i][bit] == 'pos':
                if ind == -1:
                    ind = i
                result[i][bit] = 'neg'
            elif ind == -1:
                ind = i

    for i in range(n):
        if result[i] is 'inf':
            for j in range(n):
                if j != i:
                    result[i] = max(result[i], a[j], min(b[j], c[j]))
                    break

    return ''.join(result)

