        else:
            return s[0] + s[1] * s[2]
    else:
        alphabet = []
        for i in range(n):
            alphabet.append(chr(ord('a') + i))
        if p == 2:
            return alphabet[1] + alphabet[0] + alphabet[2]
        elif p == 3:
            return club_sort(alphabet)
        else:
            return alphabet[n - 1] + club_sort(alphabet)

def club_sort(alphabet):
    sorted_alphabet = sorted(alphabet)
    while len(sorted_alphabet) > 2 and sorted_alphabet[-1] == alphabet[0]:
        sorted_alphabet.pop()
    if len(sorted_alphabet) > 2:
        for i in range(len(sorted_alphabet) - 1):
            if sorted_alphabet[i] > sorted_alphabet[i + 1]:
                sorted_alphabet[i + 1], sorted_alphabet[i + 2] = sorted_alphabet[i + 2], sorted_alphabet[i + 1]
        return ''.join(sorted_alphabet)
    return ''.join(sorted_alphabet)

def solve(N, P, S):
