from collections import defaultdict

def dfs(v, visited):
    set visited[v] = True
    for u in find_neighbors(v):
        if not visited[u]:
            dfs(u)

def find_neighbors(v):
    return [neighbor for neighbor in neighbors[v] if not visited[neighbor]]

def TOF(graph):
    n = len(graph)
    visited = [False] * n
    neighbors = [[] for _ in range(n)]

    for u, v in graph:
        neighbors[v-1].append(u-1)

    total_dfs_calls = 0
    for v in range(n):
        if not visited[v]:
            total_dfs_calls += dfs(v, visited)

    return total_dfs_calls

def main():
    n, m = map(int, input().split())
    graph = [tuple(map(int, input().split())) for _ in range(m)]

    result = TOF(graph)
    print(result)

if __name__ == "__main__":
    main()
