# Generate all primes up to 1000
def primes_upper(limit):
    sieve = [True] * limit
    i = 2
    while i * i < limit:
        if sieve[i]:
            for j in range(i * i, limit, i):
                sieve[j] = False
        i += 1
    primes = [i for i in range(2, limit) if sieve[i]]
    return primes

primes = primes_upper(1000)

# Function to compute modular inverse using Fermat's Little Theorem
def modInverse(a, m):
    return pow(a, m - 2, m)

# Function to count number of non-isomorphic trees
def countNonIsomorphicTrees(n, d, mod):
    dp = [0] * (n + 1)
    dp[2] = 1
    for v in range(3, n + 1, 2):
        for xor in range(1, v, 2):
            if dp[v - xor] >= 2 and canHavePermutationBothDegrees(v - xor, xor, d, n):
                dp[v] = (dp[v] + dp[v - xor]) % mod
    return dp[n]

# Function to check if a permutation with degrees 'a' and 'b' is possible in the graph
def canHavePermutationBothDegrees(a, b, d, n):
    sums = {0}
    while True:
        nextSums = set()
        for x in sums:
            for y in range(max(x+d, a + b), n + 1, 2):
                if checkValid(y, a, b, n):
                    nextSums.add(y)
                    sums.add(y)
                    return True
        if len(nextSums) == 0:
            return False

# Function to check if a degree 'y' is valid
def checkValid(y, a, b, n):
    return y - a - b >= d

